"""Model pool editor used by the Windows GUI."""

import copy

from PyQt5.QtCore import Qt, QSignalBlocker
from PyQt5.QtWidgets import (
    QCheckBox, QDialog, QDialogButtonBox, QFrame, QHBoxLayout, QHeaderView, QLabel,
    QLineEdit, QMessageBox, QPushButton, QSpinBox, QTableWidget, QTableWidgetItem,
    QVBoxLayout,
)

from pdf2zh.local_config import decode_key, encode_key, load_pool_settings, save_pool_settings


def profile_from_envs(service_name, envs):
    """Import the currently configured OpenAI-compatible service, without a call."""
    prefixes = {
        "OpenAI 兼容格式": ("OPENAILIKED", ""),
        "OpenAI": ("OPENAI", "https://api.openai.com/v1"),
        "DeepSeek": ("DEEPSEEK", "https://api.deepseek.com/v1"),
        "Silicon": ("SILICON", "https://api.siliconflow.cn/v1"),
        "Zhipu": ("ZHIPU", "https://open.bigmodel.cn/api/paas/v4"),
        "Gemini": ("GEMINI", "https://generativelanguage.googleapis.com/v1beta/openai"),
        "ModelScope": ("MODELSCOPE", "https://api-inference.modelscope.cn/v1"),
        "Grok": ("GROK", "https://api.x.ai/v1"),
        "Groq": ("GROQ", "https://api.groq.com/openai/v1"),
        "Ollama": ("OLLAMA", "http://localhost:11434/v1"),
    }
    if service_name not in prefixes:
        return None
    prefix, default_url = prefixes[service_name]
    model = envs.get(prefix + "_MODEL", "") or ""
    url = envs.get(prefix + "_BASE_URL", "") or default_url
    if not model or not url:
        return None
    return {
        "enabled": True, "name": f"{service_name} · {model}", "base_url": url,
        "model": model, "api_key": encode_key(envs.get(prefix + "_API_KEY", "") or ""),
        "disable_thinking": "siliconflow" in url.lower(),
    }


class ModelPoolDialog(QDialog):
    def __init__(self, parent=None, current_profile=None):
        super().__init__(parent)
        self.setWindowTitle("多模型管理 · 自动故障切换")
        self.resize(1000, 540)
        self.settings = load_pool_settings()
        self.current_profile = current_profile
        layout = QVBoxLayout(self)
        hint = QLabel("按列表顺序选择首选模型；超时、接口报错或空回复时，自动换模型重试当前段落。\n"
                      "切换成功后继续使用可用模型；故障模型在冷却期间跳过。全部不可用时停止并保留已完成的段落缓存。")
        hint.setWordWrap(True)
        layout.addWidget(hint)
        self.table = QTableWidget(0, 6)
        self.table.setHorizontalHeaderLabels(["启用", "名称", "API 地址", "模型名", "API 密钥", "关闭思考"])
        self.table.itemChanged.connect(self._update_dirty)
        self.table.setSelectionBehavior(QTableWidget.SelectRows)
        self.table.setSelectionMode(QTableWidget.SingleSelection)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.Interactive)
        for col, width in enumerate((48, 150, 245, 200, 150, 75)):
            self.table.setColumnWidth(col, width)
        self.table.horizontalHeader().setStretchLastSection(False)
        layout.addWidget(self.table, 1)
        for profile in self.settings["profiles"]:
            self.add_profile(profile)
        if not self.settings["profiles"] and current_profile:
            self.add_profile(current_profile)
        row = QHBoxLayout()
        for text, callback in (
            ("添加阿里云", self.add_aliyun),
            ("添加空白", lambda: self.add_profile()),
            ("添加当前服务", self.add_current),
            ("复制选中", self.duplicate), ("删除", self.remove),
            ("上移", lambda: self.move(-1)), ("下移", lambda: self.move(1)),
        ):
            button = QPushButton(text)
            button.clicked.connect(callback)
            row.addWidget(button)
        layout.addLayout(row)
        aliyun_hint = QLabel("阿里云百炼：添加后填写同地域 API Key；地址可换成控制台提供的业务空间专属地址。"
                            "<a href='https://help.aliyun.com/zh/model-studio/compatibility-of-openai-with-dashscope'>官方配置说明</a>")
        aliyun_hint.setWordWrap(True)
        aliyun_hint.setOpenExternalLinks(True)
        layout.addWidget(aliyun_hint)
        controls = QHBoxLayout()
        self.timeout_spin = QSpinBox()
        self.timeout_spin.setRange(1, 600)
        self.timeout_spin.setValue(int(self.settings["request_timeout"]))
        self.timeout_spin.setSuffix(" 秒")
        self.timeout_spin.setToolTip("从开始联网到完整收到回复的总时限；超过后立即尝试下一模型。")
        self.cooldown_spin = QSpinBox()
        self.cooldown_spin.setRange(1, 3600)
        self.cooldown_spin.setValue(int(self.settings["cooldown"]))
        self.cooldown_spin.setSuffix(" 秒")
        self.qps_spin = QSpinBox()
        self.qps_spin.setRange(0, 1000)
        self.qps_spin.setValue(int(self.settings["qps"]))
        self.qps_spin.setSpecialValueText("不限速")
        self.qps_spin.setToolTip("整个模型池每秒最多发起的请求数，和翻译线程数独立；0 为不限速。")
        for label, widget in (("单次请求时限", self.timeout_spin), ("故障冷却", self.cooldown_spin), ("每秒请求数", self.qps_spin)):
            controls.addWidget(QLabel(label))
            controls.addWidget(widget)
        layout.addLayout(controls)
        note = QLabel("API 地址填写到 /v1（也可填完整 /chat/completions）；同一平台的不同模型可复制后改模型名。\n"
                      "「关闭思考」仅勾选支持 enable_thinking 参数的接口。密钥只在本机保存，列表中隐藏。")
        note.setWordWrap(True)
        note.setStyleSheet("color: #666;")
        layout.addWidget(note)
        footer = QFrame()
        footer.setObjectName("ModelSaveBar")
        footer_layout = QHBoxLayout(footer)
        footer_layout.setContentsMargins(14, 10, 10, 10)
        self.save_status = QLabel()
        self.save_status.setObjectName("SaveStatus")
        footer_layout.addWidget(self.save_status, 1)
        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        self.save_button = buttons.button(QDialogButtonBox.Save)
        self.save_button.setText("保存并启用多模型翻译")
        self.save_button.setObjectName("SaveModels")
        self.save_button.setMinimumHeight(44)
        self.save_button.setDefault(True)
        buttons.button(QDialogButtonBox.Cancel).setText("关闭")
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        footer_layout.addWidget(buttons)
        layout.addWidget(footer)
        self._saved_state = self._editor_state()
        self._import_pending = not self.settings["profiles"] and bool(current_profile)
        for spin in (self.timeout_spin, self.cooldown_spin, self.qps_spin):
            spin.valueChanged.connect(self._update_dirty)
        self._update_dirty()

    def _editor_state(self):
        # Preserve blank rows and exact edits when checking for unsaved changes.
        # Reading _profile() here would replace a blank name with a fallback.
        profiles = []
        for row in range(self.table.rowCount()):
            profiles.append((self.table.cellWidget(row, 0).isChecked(),
                             *(self.table.item(row, col).text() for col in (1, 2, 3)),
                             self.table.cellWidget(row, 4).text(),
                             self.table.cellWidget(row, 5).isChecked()))
        return (self.timeout_spin.value(), self.cooldown_spin.value(), self.qps_spin.value(), profiles)

    def has_unsaved_changes(self):
        return self._import_pending or self._editor_state() != self._saved_state

    def _update_dirty(self, *_):
        if not hasattr(self, "_saved_state"):
            return
        dirty = self.has_unsaved_changes()
        self.save_status.setText("● 有未保存的更改" if dirty else "配置已保存")
        self.save_status.setProperty("dirty", dirty)
        self.save_status.style().unpolish(self.save_status)
        self.save_status.style().polish(self.save_status)

    def add_profile(self, profile=None):
        blocker = QSignalBlocker(self.table)
        profile = profile or {}
        row = self.table.rowCount()
        self.table.insertRow(row)
        enabled = QCheckBox()
        enabled.setChecked(profile.get("enabled", True))
        enabled.toggled.connect(self._update_dirty)
        self.table.setCellWidget(row, 0, enabled)
        for col, key in ((1, "name"), (2, "base_url"), (3, "model")):
            self.table.setItem(row, col, QTableWidgetItem(str(profile.get(key, ""))))
        key_edit = QLineEdit(decode_key(profile.get("api_key", "")))
        key_edit.setEchoMode(QLineEdit.Password)
        key_edit.setPlaceholderText("本地服务可留空")
        key_edit.textChanged.connect(self._update_dirty)
        self.table.setCellWidget(row, 4, key_edit)
        thinking = QCheckBox()
        thinking.setChecked(profile.get("disable_thinking", False))
        thinking.toggled.connect(self._update_dirty)
        self.table.setCellWidget(row, 5, thinking)
        self.table.selectRow(row)
        self._update_dirty()

    def _profile(self, row):
        return {
            "enabled": self.table.cellWidget(row, 0).isChecked(),
            "name": self.table.item(row, 1).text().strip() or f"模型 {row + 1}",
            "base_url": self.table.item(row, 2).text().strip(),
            "model": self.table.item(row, 3).text().strip(),
            "api_key": encode_key(self.table.cellWidget(row, 4).text().strip()),
            "disable_thinking": self.table.cellWidget(row, 5).isChecked(),
        }

    def add_current(self):
        if self.current_profile:
            self.add_profile(copy.deepcopy(self.current_profile))
        else:
            QMessageBox.information(self, "添加当前服务", "请先选择并配置一个 OpenAI 兼容的翻译服务，或直接添加空白配置。")

    def add_aliyun(self):
        self.add_profile({"enabled": True, "name": "阿里云 · qwen-plus",
                          "base_url": "https://dashscope.aliyuncs.com/compatible-mode/v1",
                          "model": "qwen-plus", "api_key": "", "disable_thinking": True})
        key_edit = self.table.cellWidget(self.table.rowCount() - 1, 4)
        key_edit.setPlaceholderText("填写百炼 API Key")
        key_edit.setFocus(Qt.OtherFocusReason)

    def duplicate(self):
        row = self.table.currentRow()
        if row >= 0:
            self.add_profile(self._profile(row))

    def remove(self):
        row = self.table.currentRow()
        if row >= 0:
            self.table.removeRow(row)
            self._update_dirty()

    def move(self, direction):
        row = self.table.currentRow()
        target = row + direction
        if row < 0 or not 0 <= target < self.table.rowCount():
            return
        profiles = [self._profile(i) for i in range(self.table.rowCount())]
        profiles[row], profiles[target] = profiles[target], profiles[row]
        self.table.setRowCount(0)
        for profile in profiles:
            self.add_profile(profile)
        self.table.selectRow(target)

    def _save_settings(self):
        self.save_button.setFocus(Qt.OtherFocusReason)
        settings = dict(self.settings, request_timeout=self.timeout_spin.value(), cooldown=self.cooldown_spin.value(),
                        qps=self.qps_spin.value(), profiles=[self._profile(i) for i in range(self.table.rowCount())])
        try:
            from pdf2zh.local_config import validate_pool_settings
            validate_pool_settings(settings)
            save_pool_settings(settings)
        except (ValueError, OSError) as error:
            QMessageBox.warning(self, "配置未保存", str(error))
            return False
        self.settings = settings
        self._saved_state = self._editor_state()
        self._import_pending = False
        self._update_dirty()
        return True

    def accept(self):
        if not self._save_settings():
            return
        super().accept()

    def _allow_close(self):
        self.save_button.setFocus(Qt.OtherFocusReason)
        if not self.has_unsaved_changes():
            return True
        question = QMessageBox(self)
        question.setWindowTitle("模型配置尚未保存")
        question.setIcon(QMessageBox.Warning)
        question.setText("要保存对模型配置的修改吗？")
        question.setInformativeText("保存后才会用于翻译；不保存将丢弃本次修改。")
        question.setStandardButtons(QMessageBox.Save | QMessageBox.Discard | QMessageBox.Cancel)
        question.button(QMessageBox.Save).setText("保存并关闭")
        question.button(QMessageBox.Discard).setText("不保存")
        question.button(QMessageBox.Cancel).setText("继续编辑")
        question.setDefaultButton(QMessageBox.Save)
        answer = question.exec_()
        if answer == QMessageBox.Save:
            if self._save_settings():
                # The main window switches to the saved pool when accepted.
                self.done(QDialog.Accepted)
                return True
            return False
        return answer == QMessageBox.Discard

    def reject(self):
        if self._allow_close() and self.result() != QDialog.Accepted:
            super().reject()

    def closeEvent(self, event):
        if self._allow_close():
            event.accept()
        else:
            event.ignore()
